  COURSE.verses = [
    { id: "bg434", title: "Bhagavad-gita 4.34", sanskrit: "tad viddhi pranipatena pariprasnena sevaya / upadeksyanti te jnanam jnaninas tattva-darsinah", takeaway: "Knowledge is received by approaching a seer of the truth with humility (pranipata), sincere inquiry (pariprasna), and service (seva).", href: "https://vedabase.io/en/library/bg/4/34/" },
    { id: "bg42", title: "Bhagavad-gita 4.2", sanskrit: "evam parampara-praptam imam rajarsayo viduh", takeaway: "This knowledge is received through the chain of disciplic succession. The parampara is a living line of hearing and teaching.", href: "https://vedabase.io/en/library/bg/4/2/" },
    { id: "sb111727", title: "Srimad-Bhagavatam 11.17.27", sanskrit: "acaryam mam vijaniyan navamanyeta karhicit / na martya-buddhyasuyeta sarva-deva-mayo guruh", takeaway: "Know the acarya as the Lord's own representative. Never slight him, and never envy him as if he were an ordinary man.", href: "https://vedabase.io/en/library/sb/11/17/27/" },
    { id: "sb11321", title: "Srimad-Bhagavatam 11.3.21", sanskrit: "tasmad gurum prapadyeta jijnasuh sreya uttamam", takeaway: "One who wants the highest good should take shelter of a guru. Approaching a teacher is not optional in this path.", href: "https://vedabase.io/en/library/sb/11/3/21/" },
    { id: "svet623", title: "Svetasvatara Upanisad 6.23", sanskrit: "yasya deve para bhaktir yatha deve tatha gurau / tasyaite kathita hy arthah prakasante mahatmanah", takeaway: "The meaning of these teachings becomes clear to the great soul who has the same deep devotion for the guru as for the Lord.", href: "https://vedabase.io/en/library/ssr/2/" },
    { id: "ajnana", title: "Traditional guru pranama", sanskrit: "om ajnana-timirandhasya jnananjana-salakaya / caksur unmilitam yena tasmai sri-gurave namah", takeaway: "A traditional offering of respects to the guru who opens eyes that were covered by the darkness of ignorance, with the salve of knowledge.", href: "https://vedabase.io/en/search/?q=aj%C3%B1%C4%81na-timir%C4%81ndhasya" },
    { id: "g7", title: "Sri Gurvastaka, verse 7 (Visvanatha Cakravarti Thakura)", sanskrit: "saksad-dharitvena samasta-sastrair uktas tatha bhavyata eva sadbhih / kintu prabhor yah priya eva tasya vande guroh sri-caranaravindam", takeaway: "The scriptures honor the guru as directly as Hari because he is the Lord's dear servant, not because he is a second, independent God. The disciple offers that honor; a bona fide guru never claims to have become God.", href: "https://vedabase.io/en/library/transcripts/690102pu-los-angeles/" },
    { id: "g8", title: "Sri Gurvastaka, verse 8 (Visvanatha Cakravarti Thakura)", sanskrit: "yasya prasadad bhagavat-prasado yasyaprasadan na gatih kuto 'pi / dhyayan stuvams tasya yasas tri-sandhyam vande guroh sri-caranaravindam", takeaway: "By the guru's grace one receives the Lord's grace. Without that grace, there is no other sure way. Remember and honor the guru throughout the day.", href: "https://vedabase.io/en/library/transcripts/710810sb-london/" },
    { id: "ccadi145", title: "Sri Caitanya-caritamrita Adi 1.45", sanskrit: "guru krsna-rupa hana sastrera pramane / guru-rupe krsna krpa karena bhakta-gane", takeaway: "According to sastra, the guru is a form of Krishna's mercy, the way the Lord delivers his devotees.", href: "https://vedabase.io/en/library/cc/adi/1/45/" },
    { id: "ccadi147", title: "Sri Caitanya-caritamrita Adi 1.47", sanskrit: "siksa-guruke ta' jani krsnera svarupa / antaryami, bhakta-srestha, — ei dui rupa", takeaway: "The siksa-guru is understood as Krishna's own helping form, in two ways: the Lord in the heart (the caitya-guru) and the advanced devotee who teaches.", href: "https://vedabase.io/en/library/cc/adi/1/47/" },
    { id: "cc2254", title: "Sri Caitanya-caritamrita Madhya 22.54", sanskrit: "sadhu-sanga, sadhu-sanga — sarva-sastre kaya / lava-matra sadhu-sange sarva-siddhi haya", takeaway: "Even a moment's association with a genuine devotee is praised in the scriptures as carrying complete spiritual success. This is why siksa and association matter so much.", href: "https://vedabase.io/en/library/cc/madhya/22/54/" },
    { id: "guru-mukha", title: "Sri Guru-vandana (Narottama Dasa Thakura)", sanskrit: "guru-mukha-padma-vakya, cittete koriya aikya", takeaway: "Make the words from the guru's lotus mouth one with the heart. This is the essence of vani-seva.", href: "https://vedabase.io/en/library/cc/adi/1/" }
  ];

